/**
 * app/api/account/route.ts — the website's door to the app's own sign-in (13 October 2026).
 *
 * The join page (public/packages/join.html, generated by yourkey-app's lib/web/joinPage.ts) sets up a
 * buyer's Your Key account, or signs into one, before the checkout. This route makes that one call to
 * the app's sign-in server (yourkey-api: /api/auth/register or /api/auth/login) and hands back only the
 * account id. The checkout link is keyed to it, and the app finds the purchase when the buyer signs in
 * with the same email and password. The session the sign-in server opens is signed straight out, so
 * the website never holds one. Calling through here, rather than from the browser, needs no change to
 * the sign-in server's cross-site settings, and works on the private preview builds too.
 */

const AUTH = "https://yourkey-api.azurewebsites.net/api/auth";

type Refusal = "taken" | "wrong" | "busy" | "email" | "short" | "failed";

const refuse = (error: Refusal, status: number) => Response.json({ error }, { status });

export async function POST(request: Request): Promise<Response> {
  let body: { mode?: unknown; email?: unknown; password?: unknown };
  try {
    body = await request.json();
  } catch {
    return refuse("failed", 400);
  }
  const mode = body.mode === "register" || body.mode === "login" ? body.mode : null;
  if (!mode) return refuse("failed", 400);
  const email = typeof body.email === "string" ? body.email.trim() : "";
  const password = typeof body.password === "string" ? body.password : "";

  // The sign-in server limits attempts per visitor by the first address in X-Forwarded-For. Vercel
  // sets that header to the visitor's own address (a visitor cannot), so it is passed on as it is.
  const visitor = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim();

  let res: Response;
  try {
    res = await fetch(`${AUTH}/${mode}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...(visitor ? { "X-Forwarded-For": visitor } : {}) },
      body: JSON.stringify({ email, password }),
      cache: "no-store",
      signal: AbortSignal.timeout(20_000),
    });
  } catch {
    return refuse("failed", 502);
  }
  const out = (await res.json().catch(() => ({}))) as { uid?: unknown; refreshToken?: unknown; error?: unknown };

  if (res.ok && typeof out.uid === "string" && out.uid) {
    if (typeof out.refreshToken === "string") {
      // Signed straight out: the website keeps no session. Best effort; it would expire on its own.
      await fetch(`${AUTH}/logout`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ refreshToken: out.refreshToken }),
        cache: "no-store",
        signal: AbortSignal.timeout(10_000),
      }).catch(() => undefined);
    }
    return Response.json({ uid: out.uid });
  }

  const said = typeof out.error === "string" ? out.error.toLowerCase() : "";
  const error: Refusal =
    res.status === 409 ? "taken"
    : res.status === 401 ? "wrong"
    : res.status === 429 ? "busy"
    : res.status === 400 ? (said.includes("password") ? "short" : "email")
    : "failed";
  return refuse(error, res.ok ? 502 : res.status);
}
